#include <boost/numeric/interval.hpp>
#include <boost/numeric/interval/utility.hpp>
#include <array>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <cstring>
using namespace std; using boost::numeric::interval; using boost::numeric::lower; using boost::numeric::upper; using I=interval<double>;
struct AD{I v;array<I,3>g;array<array<I,3>,3>h;AD(double x=0):v(x){for(auto&z:g)z=I(0);for(auto&r:h)for(auto&z:r)z=I(0);}AD(I x):v(x){for(auto&z:g)z=I(0);for(auto&r:h)for(auto&z:r)z=I(0);}};AD var(I x,int k){AD a(x);a.g[k]=I(1);return a;}AD operator+(AD a,const AD&b){a.v+=b.v;for(int i=0;i<3;i++){a.g[i]+=b.g[i];for(int j=0;j<3;j++)a.h[i][j]+=b.h[i][j];}return a;}AD operator-(AD a,const AD&b){a.v-=b.v;for(int i=0;i<3;i++){a.g[i]-=b.g[i];for(int j=0;j<3;j++)a.h[i][j]-=b.h[i][j];}return a;}AD operator*(const AD&a,const AD&b){AD z;z.v=a.v*b.v;for(int i=0;i<3;i++){z.g[i]=a.g[i]*b.v+a.v*b.g[i];for(int j=0;j<3;j++)z.h[i][j]=a.h[i][j]*b.v+a.g[i]*b.g[j]+a.g[j]*b.g[i]+a.v*b.h[i][j];}return z;}AD operator*(double k,const AD&a){AD z=a;z.v*=k;for(int i=0;i<3;i++){z.g[i]*=k;for(int j=0;j<3;j++)z.h[i][j]*=k;}return z;}AD inv(const AD&a){AD z;I v2=a.v*a.v,v3=v2*a.v;z.v=I(1)/a.v;for(int i=0;i<3;i++){z.g[i]=-a.g[i]/v2;for(int j=0;j<3;j++)z.h[i][j]=I(2)*a.g[i]*a.g[j]/v3-a.h[i][j]/v2;}return z;}AD operator/(const AD&a,const AD&b){return a*inv(b);}AD sqrta(const AD&a){AD z;z.v=sqrt(a.v);I den=I(2)*z.v,den3=I(4)*z.v*z.v*z.v;for(int i=0;i<3;i++){z.g[i]=a.g[i]/den;for(int j=0;j<3;j++)z.h[i][j]=a.h[i][j]/den-a.g[i]*a.g[j]/den3;}return z;}AD powi(AD a,int n){AD z(1.0);for(int i=0;i<n;i++)z=z*a;return z;}
struct Term{array<int,4>e;double c,h;};static const Term T[]={{{2,2,0,0},0.048221427879876515,1.0/72},{{2,0,2,0},0.053336084763073195,1.0/72},{{1,2,1,0},0.11385707390148079,1.0/36},{{1,1,1,1},0.34286799970231569,0.07856742013183862},{{1,0,3,0},0.062043193833937075,1.0/72},{{0,2,2,0},0.06563564602160427,1.0/72},{{0,2,0,2},0.13577211811522818,1.0/36},{{0,1,2,1},0.29409213498796925,0.05892556509887896},{{0,0,4,0},0.017687575726200236,1.0/288},{{0,0,2,2},0.14600143188162157,1.0/36}};
AD rho(array<AD,3>y){array<AD,4>Y={y[0],y[1],y[2],AD(1.0)-y[0]-y[1]-y[2]},c={sqrta(Y[0]),sqrta(Y[1]),sqrta(Y[2]),sqrta(Y[3])};AD C(0),H(0);for(auto&t:T){AD m(1);for(int i=0;i<4;i++)m=m*powi(c[i],t.e[i]);C=C+t.c*m;H=H+t.h*m;}return (4.0/3.7183448981203875)*(C/sqrta(H));}
bool inv3(double A[3][3],double R[3][3]){double M[3][6]{};for(int i=0;i<3;i++){for(int j=0;j<3;j++)M[i][j]=A[i][j];M[i][3+i]=1;}for(int c=0;c<3;c++){int p=c;for(int r=c+1;r<3;r++)if(fabs(M[r][c])>fabs(M[p][c]))p=r;for(int j=0;j<6;j++)swap(M[c][j],M[p][j]);double d=M[c][c];if(fabs(d)<1e-15)return false;for(int j=0;j<6;j++)M[c][j]/=d;for(int r=0;r<3;r++)if(r!=c){double q=M[r][c];for(int j=0;j<6;j++)M[r][j]-=q*M[c][j];}}for(int i=0;i<3;i++)for(int j=0;j<3;j++)R[i][j]=M[i][3+j];return true;}
int main(){array<double,3>x0={0.063925514399,0.225843540948,0.438542296078};array<I,3>X={I(x0[0]-1e-5,x0[0]+1e-5),I(x0[1]-1e-5,x0[1]+1e-5),I(x0[2]-1e-5,x0[2]+1e-5)};cout<<setprecision(17);for(int it=0;it<5;it++){array<AD,3>AX,A0;for(int i=0;i<3;i++){AX[i]=var(X[i],i);A0[i]=var(I(x0[i]),i);}AD RX=rho(AX),R0=rho(A0);double J0[3][3],CI[3][3];for(int i=0;i<3;i++)for(int j=0;j<3;j++)J0[i][j]=(lower(R0.h[i][j])+upper(R0.h[i][j]))/2;inv3(J0,CI);array<I,3>K;bool ok=true;for(int i=0;i<3;i++){I z(x0[i]);for(int k=0;k<3;k++)z-=CI[i][k]*R0.g[k];for(int j=0;j<3;j++){I rr(i==j?1.0:0.0);for(int k=0;k<3;k++)rr-=CI[i][k]*RX.h[k][j];z+=rr*(X[j]-x0[j]);}K[i]=intersect(z,X[i]);if(lower(K[i])>=upper(K[i]))ok=false;}cout<<"it "<<it<<" rhoX ["<<lower(RX.v)<<", "<<upper(RX.v)<<"]\n";for(int i=0;i<3;i++)cout<<" X"<<i<<" ["<<lower(X[i])<<", "<<upper(X[i])<<"] K ["<<lower(K[i])<<", "<<upper(K[i])<<"]\n";if(!ok)return 2;X=K;}
 array<AD,3>AF;for(int i=0;i<3;i++)AF[i]=var(X[i],i);AD RF=rho(AF);cout<<"FINAL rho ["<<lower(RF.v)<<", "<<upper(RF.v)<<"]\n";}
